function test_author_reference_export()
% Deterministic fixture-export smoke test using SYNTHETIC .mat inputs.
% No author solution, fsolve, or GE result is generated by this test.
root=tempname;
mkdir(root);
input=fullfile(root,'author');
output=fullfile(root,'fixtures');
mkdir(input);
T=200;
kl_path=(1:399)';
kl_exp=kl_path + 0.1;
G0_shock=zeros(769,7);
G0_shock(129,1)=1;
params.k_initial=27;
params.q_initial=0.99;
params.BG_shock=-3.5;
params.tot_initial=0.97;
params.k_final=26;
params.beta=0.9832;
params.k_const_hat=0;
resid=zeros(399,1);
tot_exp=0.92*ones(T,1);
save(fullfile(input,'exp_flex.mat'),'kl_path','kl_exp','G0_shock', ...
     'params','resid','tot_exp');
kl_exp=kl_path+0.2;
save(fullfile(input,'exp_flex_lev16.mat'),'kl_exp','G0_shock', ...
     'params','resid','tot_exp');
k_l_t_fixed=[kl_exp;1.01*ones(T,1)];
resid=zeros(599,1);
tot_fixed=1.01*ones(T,1);
save(fullfile(input,'exp_both_41_lev16.mat'), ...
     'k_l_t_fixed','resid','tot_fixed','G0_shock','params');
export_author_reference_fixtures(input,output);
expected={'original_boom_candidate','shock_pre_distribution', ...
          'shock_inherited_metadata'};
for label={'unleveraged','leveraged','fixed'}
    for suffix={'candidate','source_residual','source_terms'}
        expected{end+1}=[label{1} '_' suffix{1}];
    end
end
assert(numel(expected)==12);
for i=1:numel(expected)
    f=fullfile(output,[expected{i} '.csv']);
    assert(exist(f,'file')==2);
    data=dlmread(f,',');
    assert(all(isfinite(data(:))));
end
assert(isequal(dlmread(fullfile(output,'original_boom_candidate.csv'),','), ...
               (1:399)'));
assert(size(dlmread(fullfile(output,'shock_pre_distribution.csv'),','),1)==769);
assert(numel(dlmread(fullfile(output,'unleveraged_candidate.csv'),','))==399);
assert(numel(dlmread(fullfile(output,'leveraged_candidate.csv'),','))==399);
assert(numel(dlmread(fullfile(output,'fixed_candidate.csv'),','))==599);
fprintf('SYNTHETIC AUTHOR REFERENCE EXPORT SMOKE PASS: 12 files, 399/399/599, source dimensions preserved\n');
rmdir(root,'s');
end
